test('controlled continuation executor runs source-locked bounded children to230 under one stage journal per owner',async()=>{await fixture(async()=>{const original=[...state.objects],result=await executor.executeNativeHostedMigrations(input);assert.equal(result.status,'COMMITTED',JSON.stringify({result,events:state.events,children:state.children}));assert.deepEqual(state.children,[124,144,164,180,200,220,230]);assert.equal(state.commands,7);assert.equal(result.stages.length,4);assert.equal(result.stages[0].status,'NOOP');assert.ok(result.stages.slice(1).every(stage=>stage.status==='COMMITTED'));for(const[path,bytes]of original)assert.equal(state.objects.get(path),bytes);const installed=JSON.parse(state.vault.get('cuevo_schema_'+ref)!);assert.equal(installed.migrationCount,230);const newRecords=[...state.objects].filter(([path])=>!original.some(([before])=>before===path)&&path.endsWith('.record.json')),groups=new Map<string,string[]>();for(const[path,bytes]of newRecords){const key=path.slice(0,path.lastIndexOf('/'));groups.set(key,[...(groups.get(key)??[]),JSON.parse(bytes).payload.state]);}assert.equal(groups.size,3);for(const states of groups.values())assert.deepEqual(states,['INTENT','COMMITTED']);const receipts=[...state.vault].filter(([name])=>name.startsWith('cuevo_batch_prefix_')).map(([,bytes])=>JSON.parse(bytes));assert.equal(receipts.length,6);assert.deepEqual(receipts.map(receipt=>receipt.index),[1,2,3,1,2,3]);assert.ok(receipts.every(receipt=>receipt.stageCommitment==='NOT_CONFIRMED'));for(let index=0;index<receipts.length;index++)if(receipts[index].index>1){assert.equal(receipts[index].previousReceiptSha256,receipts[index-1].receiptSha256);assert.equal(receipts[index].beforeHistorySha256,receipts[index-1].afterHistorySha256);}assert.equal(result.hostedAcceptance,false);});});
